$ErrorActionPreference = "Stop"
$ProjectRoot = "H:\MNTrapTeam\MNTrapTeam"
$Version = "4.8.3"

if (-not (Test-Path (Join-Path $ProjectRoot "mntrapteam"))) {
    throw "MNTrapTeam project not found at $ProjectRoot"
}

Write-Host "Installing MNTrapTeam $Version Grand browser pagination tool..."

$payload = ""
[IO.File]::WriteAllBytes(
    (Join-Path $ProjectRoot "mntrapteam\grand_browser_pagination_cli.py"),
    [Convert]::FromBase64String($payload)
)

Set-Content -Path (Join-Path $ProjectRoot "VERSION") -Value $Version -Encoding UTF8

Set-Location $ProjectRoot
& ".\.venv\Scripts\python.exe" -m py_compile ".\mntrapteam\grand_browser_pagination_cli.py"
if ($LASTEXITCODE -ne 0) { throw "Syntax check failed." }

Write-Host ""
Write-Host "MNTrapTeam 4.8.3 installed."
Write-Host "Run:"
Write-Host '& ".\.venv\Scripts\python.exe" -m mntrapteam.grand_browser_pagination_cli --shoot-id 1331'
